            unique(self.choices()), bounded(self.choices(),self.view()),
            above(self.choices(),self.base()), state_above(self.view(),self.base()),
            operation_ids(self.view(),self.base()),
    { use_type_invariant(self); }
    pub proof fn domain(tracked &self)
